from confluent_kafka import Producer

conf = {'bootstrap.servers': 'broker1:9092,broker2:9092',
        'linger.ms': 5,  # small wait to allow batching
        'batch.size': 16384}

p = Producer(conf)

def delivery_report(err, msg):
    if err is not None:
        print('Delivery failed:', err)
    else:
        print('Delivered message to {} [{}]'.format(msg.topic(), msg.partition()))

for i in range(1000):
    p.produce('events-topic', key=str(i % 100), value='event-'+str(i), callback=delivery_report)
    # let producer background thread send
    p.poll(0)

p.flush()

