// Minimal orchestrator pattern (pseudo-Node.js)
async function runSaga(steps) {
  const completed = []
  try {
    for (const step of steps) {
      const result = await step.action()
      completed.push(step)
    }
    return { status: 'success' }
  } catch (err) {
    // run compensations in reverse order
    for (const step of completed.reverse()) {
      try { await step.compensate() } catch (e) { console.error('compensation failed', e) }
    }
    return { status: 'compensated', error: err.message }
  }
}

// Usage:
// runSaga([{ action: charge, compensate: refund }, { action: reserveInventory, compensate: releaseInventory }])
